custom_css:
/*
主题：灰调雾面
作者：discord@无
发布于lc、wbz，可二改。二传什么的还是不要了吧！
感恩旅程墨千尾老师的美化教程，感恩补充撰写拼好码的老师们，感恩小红书的毛毛雨老师，感恩gemini，感恩一切……
*/

/* 先导篇：字体导入*/
@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
    font-family: "KingHwaOldSong";
    font-weight: normal;
}

/* === 一、全局控制 === */
:root {
  --字体1: 'KingHwaOldSong';
  --自定义思维链文案: "Thinking...";
  --自定义“加载更多信息”文案: "加载更早的消息";
  --自定义输入框文字: "写给你的情诗...";

  /* --- 灰蓝调色盘 --- */
  --ins-bg: #ffffff;      /* 全局背景：白 */
  --ins-card: #ffffff;    /* 卡片底色：白 */
  --ins-text: #7f7f7f; 
  --ins-accent: #7d8ba4;  /* 强调色：低饱和度中灰蓝（用于图标、副文本） */
  --ins-border: #d9e2ec;  /* 边框色：浅灰蓝 */
}

body {
  font-family: var(--字体1);
  color: var(--ins-text);
}

/* 全局弹出面板主色调 */
.drawer-content, 
#table_drawer_content, 
.options-content {
  background-color: var(--ins-card) !important;
  border-color: #ffffff;
}

/* 全局重置 */
* {
    filter: none !important;
    outline: none !important;
    box-shadow: none !important;
}

/* === 二、顶栏 === */

/* 1. 清空并隐藏原有的图标 */
#top-settings-holder .drawer-icon::before {
  content: "" !important;
  display: none !important;
}

/* 2. 所有自定义图标的【通用样式】（尺寸、对齐、动画） */
#top-settings-holder .drawer-icon {
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 24px !important; 
  height: 24px !important;
  opacity: 1;
  transition: transform 0.2s ease-in-out, filter 0.2s ease-in-out;
  display: inline-block !important; /* 确保容器有长宽能显示背景图 */
}

/* 3. 分别为每个按钮指定你的【图片地址】 */
#ai-config-button .drawer-icon {
    background-image: url('https://img.heliar.top/file/1776315252713_IMG_4374.png') !important; 
}
#advanced-formatting-button .drawer-icon { 
    background-image: url('https://img.heliar.top/file/1776314679436_IMG_4371.png') !important; 
}
#user-settings-button .drawer-icon { 
    background-image: url('https://img.heliar.top/file/1776309392800_IMG_4362.png') !important; 
}

#extensions-settings-button .drawer-icon { 
    background-image: url('https://img.heliar.top/file/1776310712150_IMG_4365.png') !important; 
}
#persona-management-button .drawer-icon { 
    background-image: url('https://img.heliar.top/file/1776312060069_IMG_4367.png') !important; 
}
#sys-settings-button .drawer-icon { 
    background-image: url('https://img.heliar.top/file/1776310719184_IMG_4364.png') !important; 
}
#WI-SP-button .drawer-icon { 
    background-image: url('https://img.heliar.top/file/1776313779230_IMG_4368.png') !important; 
}
#backgrounds-drawer-toggle .drawer-icon { 
    background-image: url('https://img.heliar.top/file/1776309404202_IMG_4356.png') !important; 
}
#rightNavHolder .drawer-icon { 
    background-image: url('https://img.heliar.top/file/1776310990722_IMG_4366.png') !important; 
}
#gaigai-top-btn{ 
    background-image: url('https://img.heliar.top/file/1776315046083_IMG_4373.png'); 
}
/*horae时光记忆*/ #horae_drawer_icon { background-image: url('https://img.heliar.top/file/1776315046083_IMG_4373.png'); }
#top-settings-holder .drawer-icon:hover {
  transform: scale(1.1);
}

/* 底栏文字 */
#send_textarea::placeholder {
    color: transparent !important; /* 隐藏系统默认的占位符 */
    text-shadow: none !important;
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--自定义输入框文字);
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 0.5em;
    pointer-events: none;
    z-index: 10;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px);
    color: rgba(175, 175, 175, 1);
    font-style: italic;
}

#nonQRFormItems {
    margin: 5px 5px;
}

#send_form [class*="fa-"]::before {
  font-size: 20px; 
  color: var(--ins-accent) !important;
  transition: color 0.2s;
}
#send_form [class*="fa-"]:hover::before {
  color: var(--ins-text) !important;
}


/* === 四、聊天区域 === */

/* 1. 聊天区域全局背景 */
#chat {
  background-color: transparent !important; 
  backdrop-filter: none !important; 
  -webkit-backdrop-filter: none !important; 
}

/* 2. 聊天气泡 */
.mes {
    display: flex; 
    flex-direction: column !important; /* 整体保持：头像栏在上，文字在下 */
    align-items: flex-start; 

    /* 毛玻璃核心代码 */
    background: rgba(255, 255, 255, 0.25) !important;
    backdrop-filter: blur(12px) saturate(120%) !important;
    -webkit-backdrop-filter: blur(12px) saturate(120%) !important; /* Safari兼容 */
    border: 1px solid rgba(255, 255, 255, 0.5) !important;
    box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.04) !important;

    border-radius: 16px; /* 圆角 */
    padding: 20px !important; 
    margin-top:44px!important;
    margin-bottom: 24px; 
    gap: 12px;
}

/* 3.三元素排版 */
.mes .mesAvatarWrapper {
    display: inline-flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: flex-start !important;
    gap: 13px !important;

/* === 核心：拟态透明毛玻璃 === */
    background: rgba(255, 255, 255, 0.4) !important; /* 半透明白底，保持清爽 */
    backdrop-filter: blur(16px) saturate(120%) !important;
    -webkit-backdrop-filter: blur(16px) saturate(120%) !important; /* Safari 兼容 */
    border: none !important;
    box-shadow: 0 8px 24px rgba(125, 139, 164, 0.08) !important; /* 保留极淡的悬浮阴影，防止融入背景 */
    border-radius: 53px !important; /* 大圆角胶囊状 */

    /* === 尺寸与内边距 === */
    padding: 6px 20px 6px 6px !important;
    width: max-content !important;
    max-width: 110% !important;

    /* === 核心：跨越边界，向上悬浮 === */
    margin-top: -60px !important; 
    margin-left: -8px !important; 
    margin-bottom: 12px !important; 

    position: relative !important;
    z-index: 10 !important; 

    flex-wrap: nowrap !important;
    pointer-events: none !important;
}

/* 确保内部文字点击事件正常 */
.mes .avatar,
.mes .ch_name,
.mes .mes_time {
    pointer-events: auto !important; 
}
.mes .ch_name {
    color: var(--ins-accent) !important; 
    font-weight: 600 !important;
    text-shadow: 0 1px 2px rgba(255, 255, 255, 0.5) !important; /* 增加一点点白光描边，防止被深色背景吞没 */
}
.mes .mes_time {
    color: #9aa8bc !important;
    font-size: 0.85em !important;
    margin-left: 2px !important;
}

/* 4.头像框 */
.mes .avatar {
    width: 53px !important; 
    height: 53px !important;
    position: relative !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-shrink: 0 !important;
    border-radius: 50% !important;
    box-shadow: 0 6px 12px rgba(125, 139, 164, 0.5) !important; 
}

.mes .avatar img {
    width: calc(100% - 2px) !important;
    height: calc(100% - 2px) !important;
    outline: none !important; 
    border-radius: 50% !important;
    padding: 0px !important; 
    object-fit: cover !important; 
    transition: all 0.2s ease !important; 
    border: none !important; 
    box-shadow: none !important; 
}
.mes .avatar::after {
    content: '' !important;
    position: absolute !important;
    top: 0px !important;
    left: 0px !important;
    right: 0px !important;
    bottom: 0px !important;
    border-radius: 50% !important;    
    border: 2px solid #ffffff !important;
    pointer-events: none !important;
    z-index: 2 !important; /* 层级高于图片 */
}
.mes .avatar::before {
    content: '' !important;
    position: absolute !important;
    top: -2px !important; /* 向外扩 2px */
    left: -2px !important;
    right: -2px !important;
    bottom: -2px !important;
    border-radius: 50% !important;

    /* 次级极细半透明圈 */
    border: 1px solid rgba(255, 255, 255, 0.8) !important;
    pointer-events: none !important;
    z-index: 0 !important;
}

/* 5.消除最后一条消息大间距 */
.mes.last_mes .mesAvatarWrapper {
    padding-bottom: 0px !important; 
}

/* 6.文字排版 */
.mes .mes_text {
  padding: 0px !important; 
  width: 100% !important; 
  text-align: justify !important;
  line-height: 1.8; /* 行高 */
}

/* 7.引用文本美化 */
.mes_text q {
    background-color: rgba(125, 139, 164, 0.06);
    border-bottom: 0.5px solid #c0cee5;
    margin: 12px 0;
    padding: 4px 4px;
    border-radius: 12px 12px 12px 12px;
    font-style: italic;
    box-shadow: 2px 2px 12px rgba(0, 0, 0, 0.015);
    line-height: 1.9;
}
blockquote {
    background:#ffffff !important;
    border-left-color: #a4b0c4!important;
    border-radius: 0px;
    padding: 5px 12px !important;
    margin: 5px auto !important;
}

code {
    background: #ffffff!important;
    border-radius: 5px;
    color: #A4B0C4;
    padding: 2px !important;
}

/* === 五、整体布局 === */
/* 滚动条极简化 */
::-webkit-scrollbar {
    width: 6px; 
    height: 6px; 
    background-color: transparent; 
}
::-webkit-scrollbar-track {
    background-color: transparent; 
}
::-webkit-scrollbar-thumb {
    background-color: var(--ins-border);
    border-radius: 10px;
    border: none; 
}

/* 多选框 */
input[type='checkbox'] {
    appearance: none !important;
    -webkit-appearance: none !important;
    width: 20px !important;
    height: 20px !important;
    border-radius: 6px !important;
    margin: 3px 0px;
    vertical-align: middle;
    background: #ffffff !important;
    border: 2px solid #A4B0C4 !important;
    box-shadow: none !important;
    transition: all 0.2s ease !important;
    position: relative;
    cursor: pointer;
}

input[type='checkbox']:hover {
    border-color: #A4B0C4 !important;
}

input[type='checkbox']:checked {
    background: #A4B0C4 !important;
    border-color: #A4B0C4!important;
box-shadow: none !important;

}

/* 单选框 */
input[type="radio"] {
    appearance: none !important;
    -webkit-appearance: none !important;
    width: 20px !important;
    height: 20px !important;
    margin: 3px 0px;
    border-radius: 50% !important;
    background: #ffffff !important;
    border: 2px solid #A4B0C4 !important;
    box-shadow: none !important;
    transition: all 0.2s ease !important;
    position: relative;
    cursor: pointer;
}

input[type="radio"]:hover {
    border-color: #A4B0C4 !important;
}

input[type="radio"]:checked {
    border: 6px solid #A4B0C4 !important;
    background: #ffffff !important;
box-shadow: none !important;
}

/* 滑块*/
input[type=range] {
    height: 24px !important; /* 增加整体触控区域防止误触 */
    background: none !important;
    border: none !important;
    box-shadow: none !important;
    width: 100% !important;
    cursor: pointer;
}

/* 滑轨*/
input[type=range]::-webkit-slider-runnable-track {
    height: 6px;
    background: #e8eaed !important;
    border: none !important;
    border-radius: 4px;
    box-shadow: none !important;
}

/* 滑块 */
input[type="range"]::-webkit-slider-thumb {
    width: 18px;
    height: 18px;
    border-radius: 50% !important;
    border: 2px solid #ffffff !important;
    background: #A4B0C4 !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15) !important; 
    margin-top: -6px !important;
    transition: transform 0.1s;
}

input[type="range"]::-webkit-slider-thumb:hover {
    transform: scale(1.15);
}

.inline-drawer-content,
#wiActivationSettings,
#wiSliders {
    background: none !important;
    padding: 0px;
}

/* 标题 */
strong::before, b::before, h4:not(.margin0) span::before, #persona-management-button.drawer .standoutHeader::before {
  margin-right: 6px;
}
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader, .inline-drawer-header {
  border: none;
  background-image: none !important;
  font-weight: normal !important;
  font-size: 1em;
  border-radius: 12px 12px 12px 12px;
  background-color: rgba(125, 139, 164, 0.06);
  border-bottom: 2px solid #c0cee5;
    box-shadow: 2px 2px 12px rgba(0, 0, 0, 0.015);
    line-height: 1.7;
    padding: 6px 6px;
}

/*下拉框*/
:is(.select2-container--default .select2-selection--single,
.text_pole, select, .text_input,
textarea:not(#send_textarea)) {
    background: #fff !important;
    border: 1px solid rgb(220 220 220 / 0.5) !important;
    color: var(--ink-deep) !important;
    border-radius: 10px !important;
    box-shadow: unset !important;
}
input[type=number] {
    background: #fff !important;
    border: 1px solid rgb(220 220 220 / 0.5) !important;
    color: var(--ink-deep) !important;
    border-radius: 8px !important;
}
.inline-drawer-content { background: transparent !important }

/* 预设部分ui 感谢毛毛雨老师 */
#completion_prompt_manager_list {
    padding: 8px !important;
}
.completion_prompt_manager_header {
    color: #5a5a5a !important;
}
.prompt-manager-inspect-action  {
    color: #5a5a5a !important;
}
/* 条目基础样式 */
.completion_prompt_manager_prompt {
    overflow: visible !important;
    padding: 7px 15px !important;
    margin: 3px 0 !important;
    background: none !important;
    border: none !important;
    border-radius: 8px !important;
    transition: all 0.2s !important;
}
.completion_prompt_manager_prompt_disabled {
    opacity: 0.3;
}
.completion_prompt_manager_prompt:hover {
    background: white !important;
    padding-left: 24px !important;
}

/* 用户管理页面 */

.avatar-container {
    transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
    border-radius: 14px !important; /* 大圆角头像框 */
    background: #ffffff !important;
    border: 1.6px solid transparent !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.02) !important;
    padding: 6px !important;
    margin: 0px !important; 
    opacity: 0.6; /* 未选中时稍微透明降噪 */
    cursor: pointer;
}

.avatar-container.selected {
    opacity: 1;
    transform: translateY(-4px) !important;
    border-color: #A4B0C4 !important;
    box-shadow: 0 8px 16px rgba(138, 180, 248, 0.15) !important;
}

/* 弹窗 */

#toast-container > .toast {
    top: 30px !important;
    margin: 10px auto !important;
    width: 80% !important;
    max-width: 400px !important;
    min-height: auto;

    background-image: none !important;
    background-color: rgba(255, 255, 255, 0.4) !important;
    backdrop-filter: blur(13px); /* 毛玻璃效果 */
    -webkit-backdrop-filter: blur(10px);

    border: 1px solid #e8eaed !important;
    border-radius: 16px !important;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.05) !important; 

    color: #abaaaa !important;
    padding: 16px 24px !important;
    transition: all 0.3s ease;
}

.toast-title {
    color: #A4B0C4 !important;
    letter-spacing: 0.5px;
    border-bottom: none !important; 
    padding-bottom: 0px;
    margin-bottom: 6px !important;
    font-weight: 600 !important;
    font-size: 15px;
}

/* === 六、正则+脚本易读+防误触 === */
#saved_regex_scripts,
#saved_scoped_scripts,
#saved_preset_scripts,
#global-script-list,
#character-script-list {
  margin-right: 80px !important;
}

/* 统一扁平卡片风 */
.regex-script-label.flex-container,
.flex-container .script-item {
  flex-wrap: wrap !important;
  padding: 10px 14px; 
  border-radius: 10px; 
  margin-bottom: 8px; 
  background: var(--ins-card); 
  border: 1px solid var(--ins-border); 
}

.regex-script-label.flex-container .regex_script_name,
.script-item .script-item-name {
  flex-basis: 100%;
  word-break: break-word; 
  font-weight: 500;
  font-size: 14px;
  color: var(--ins-text);
}


/* === 七、“加载更多消息”美化 === */
#show_more_messages {
  font-size: 0 !important;
  color: transparent !important; 
  display: block;
  padding: 8px 24px;
  margin: 20px auto; 
  width: fit-content; 
  background-color: transparent; 
  border: 1px solid var(--ins-border); /* 胶囊状细线按钮 */
  border-radius: 30px; 
  box-shadow: none; 
  cursor: pointer;
  transition: all 0.3s ease;
}

#show_more_messages::before {
  content: var(--自定义“加载更多信息”文案); 
  font-size: 12px !important; 
  color: var(--ins-accent) !important; 
  font-weight: 500;
}

#show_more_messages:hover {
  background-color: var(--ins-border);
}
#show_more_messages:hover::before {
  color: var(--ins-text) !important; 
}


/* === 八、思维链美化 === */
.mes_reasoning_summary {
  list-style: none; 
  cursor: pointer;
  display: flex !important;
  align-items: center;
}

.mes_reasoning_header {
  background: transparent; 
  border: 1px solid var(--ins-border); 
  border-radius: 30px; /* 胶囊型 */
  padding: 6px 18px;
  transition: all 0.2s ease;
}

.mes_reasoning_summary:hover .mes_reasoning_header {
  background: var(--ins-bg);
}

.mes_reasoning_header_title {
  font-size: 0 !important;
}
.mes_reasoning_header_title::before {
  content: var(--自定义思维链文案); 
  font-size: 13px; 
  color: var(--ins-accent); 
  font-weight: normal; 
}

.mes_reasoning_arrow {
  font-size: 0 !important;
}
.mes_reasoning_arrow::before {
  content: ' ';
  font-size: 16px; 
  color: var(--ins-accent);
  display: inline-block; 
  transition: transform 0.2s ease;
  margin-right: 4px;
}
details[open] .mes_reasoning_arrow::before {
  transform: rotate(90deg);
}

.mes_reasoning {
  margin-top: 10px; 
  padding: 12px 16px;
  background-color: var(--ins-bg);
  border-left: 3px solid var(--ins-border); /* 左侧细线指引 */
  border-radius: 0 8px 8px 0; 
  color: var(--ins-accent); 
  font-size: 14px;
  line-height: 1.6;
}


/* === 九、收藏栏左右滑动查看角色 === */
.hotswap.avatars_inline {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  padding-right: 15px;
}
.hotswap.avatars_inline::-webkit-scrollbar {
  display: none; 
}
.hotswap.avatars_inline {
  scrollbar-width: none;
} 

/* 手机端妥协方案 */
@media (max-width: 768px) {
  .hotswap.avatars_inline {
    overflow: auto;
  }
}
/* 来自 s 老师 - 抽屉圆角修正 */
.drawer-content, #extensionTopBar {
    border-radius: 0 !important;
}
